"""Hand-authored release 0.10 content; run once against 0.9. YAML is authoritative."""
import json,re,copy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
cat=json.loads((ROOT/'content/catalog.yaml').read_text())
existing={m['id']:m for m in cat['courses'][-1]['modules']}
all_new=[]
def start(key,title,obj,urls,extend=False):
 global meta,tasks,cards
 meta=(key,title,obj,urls,extend);tasks=[];cards=[]
def base(title,prompt,explain,hint):
 key,title_m,obj,urls,ext=meta;n=len(tasks)+1
 tid=f'encor.{key}.'+('ext.' if ext else '')+f'{n:02}'
 d=([2,3,3] if ext else [1,2,3])[(n-1)//6]
 common=dict(id=tid,revision=1,title=title,skills=[f'{key}.'+re.sub(r'[^a-z0-9]+','-',title.lower()).strip('-')],sources=[dict(title='Dokumentacja Cisco — '+title_m,url=u) for u in urls])
 return dict(common,blueprint_refs=[dict(exam='350-401',version='1.2',objective=obj)],difficulty=d,prompt_md=prompt,hints=[hint or explain],explanation_md=explain,card_id=tid+'.theory')
def card(t,example):
 cards.append({k:t[k] for k in ['revision','title','skills','sources']}|dict(id=t['card_id'],front_md=t['title'],back_md=t['explanation_md'],example=example));tasks.append(t)
def q(title,prompt,answer,wrong,explain,hint=''):
 t=base(title,prompt,explain,hint);n=len(tasks);pos=(n*3+n//6)%4
 opts=[]
 for w in wrong:
  text,reason=w.split('|',1);opts.append(dict(text_md=text,feedback_md=reason))
 opts.insert(pos,dict(text_md=answer,feedback_md=explain));assert len(opts)==4
 for i,o in enumerate(opts):o['id']='ABCD'[i]
 t.update(type='single_choice',options=opts,correct_option_id='ABCD'[pos]);card(t,answer)
def c(title,prompt,template,values,explain,hint=''):
 t=base(title,prompt,explain,hint);blanks=[];example=template
 for i,v in enumerate(values):
  if isinstance(v,str):a=[v];typ='command'
  else:a,typ=v
  blanks.append(dict(id=f'b{i}',label=f'Luka {i+1}',answer_type=typ,accepted=a,width=min(56,max(6,len(a[0])+2)),common_errors={}))
  example=example.replace('{{b'+str(i)+'}}',a[0])
 t.update(type='cli_fill_blank',platform='Cisco IOS / IOS XE; zgodnie z założeniami zadania',template=template,blanks=blanks);card(t,example)
def end():
 key,title,obj,urls,ext=meta;assert len(tasks)==18,(key,len(tasks))
 module=existing.get('encor.'+key) if ext else dict(id='encor.'+key,title=title,description='Od pojęć do analizy i praktycznych scenariuszy.',stages=[])
 if not ext:
  assert module['id'] not in existing
  cat['courses'][-1]['modules'].append(module)
 start_order=len(module['stages'])
 for i in range(3):
  order=start_order+i+1;sid=f'encor.{key}.stage-{order}';path=f'content/encor/{key}/stage-{order}.yaml'
  p=ROOT/path;assert not p.exists(),path;p.parent.mkdir(parents=True,exist_ok=True)
  p.write_text(json.dumps(dict(schema_version=3,id=sid,revision=1,cards=cards[i*6:i*6+6],tasks=tasks[i*6:i*6+6]),ensure_ascii=False,indent=2)+'\n')
  module['stages'].append(dict(id=sid,title=(['Rozszerzenie — zależności','Rozszerzenie — konfiguracja','Rozszerzenie — diagnostyka'] if ext else ['Podstawy','Zastosowanie','Scenariusze'])[i],description='Sześć zadań z teorią i wyjaśnieniem odpowiedzi.',difficulty=tasks[i*6]['difficulty'],order=order,pack_url='/'+path.replace('.yaml','.json'),pack_revision=1,task_count=6,pass_percent=80,requires=[] if order==1 else [f'encor.{key}.stage-{order-1}']))
 all_new.extend(tasks)


def Q(title,prompt,options,explain):
 q(title,prompt,options[0],[x+'|'+explain for x in options[1:]],explain,'Przeanalizuj warunki scenariusza; odpowiedź dotyczy wyłącznie podanych założeń.')
def C(title,prompt,template,values,explain):
 c(title,prompt,template,values,explain,'Zwróć uwagę na tryb konfiguracji i parametry wymienione w poleceniu.')
def save():
 assert len(all_new)==72,len(all_new)
 cat['revision']+=1
 (ROOT/'content/catalog.yaml').write_text(json.dumps(cat,ensure_ascii=False,indent=2)+'\n')
 print('Added',len(all_new),'ENCOR tasks')
FNF='https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/ntw-servs/b-network-services/m_fnf-fnetflow.html'
FNF4='https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/ntw-servs/b-network-services/m_fnf-ipv4-uni.html'
REST='https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/configuration/1713/b_1713_programmability_cg/m_1713_prog_restconf.html'
NET='https://developer.cisco.com/docs/ios-xe-voip/getting-started/'
ACL='https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/configuration/1716/b_1716_programmability_cg/netconf-and-restconf-service-level-acls.html'
COPP='https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/qos_plcshp/configuration/xe-16-11/qos-plcshp-xe-16-11-book/qos-plcshp-ctrl-pln-plc.html'
start('netflow','Flexible NetFlow — rekord, monitor i eksport','4.2',[FNF,FNF4])
Q('Trzy elementy FNF','Który element Flexible NetFlow definiuje pola identyfikujące przepływ i zbierane dane?', ['Flow record','Flow exporter','Adres kolektora','Interfejs source eksportera'],'Record opisuje strukturę danych. Exporter określa wysyłanie, a monitor łączy rekord z cache i opcjonalnym eksportem.')
Q('Pola kluczowe','Czym różnią się match i collect w rekordzie FNF?', ['Match tworzy klucz przepływu; collect dodaje dane niekluczowe','Collect zawsze filtruje ACL, match szyfruje','Match jest adresem kolektora, collect portem UDP','Oba służą wyłącznie do zmiany DSCP'],'Różne wartości pól match rozdzielają przepływy. Pola collect opisują przepływ, np. liczniki pakietów.')
C('Adres źródłowy w rekordzie','W rekordzie REC dodaj adres źródłowy IPv4 jako pole kluczowe.','flow record REC\n match ipv4 {{b0}} address',['source'],'Adres źródłowy jest częścią klucza; użycie destination oznaczałoby adres docelowy.')
Q('NetFlow a przechwytywanie','Czy standardowe rekordy NetFlow zawierają pełny payload każdego pakietu jak przechwyt Wiresharka?', ['Nie, opisują przepływy i wybrane metadane','Tak, każdy rekord to cały plik PCAP','Tak, jeśli użyto UDP 2055','Nie, bo nie zawierają żadnych liczników'],'NetFlow opisuje komunikację i jej wielkość. Do analizy pełnej zawartości pakietów potrzebny jest przechwyt.')
C('Adres kolektora','Exporter EXP ma wysyłać dane do kolektora 192.0.2.50.','flow exporter EXP\n destination {{b0}}',['192.0.2.50'],'Destination wskazuje odbiorcę danych telemetrycznych, a nie cel obserwowanych przepływów.')
Q('Powiązanie elementów','Który element łączy rekord, cache i exporter?', ['Flow monitor','Class-map QoS','Trasa domyślna','ACL VTY'],'Monitor określa rekord i sposób utrzymywania danych oraz może wskazywać exporter. Następnie jest przypinany do interfejsu.')
Q('Kierunek obserwacji','Na Gi0/0 skonfigurowano ip flow monitor MON input. Który ruch obserwuje ten punkt?', ['Wchodzący do routera przez Gi0/0','Tylko eksport wychodzący do kolektora','Wyłącznie ruch wytworzony przez CPU','Tylko pakiety opuszczające Gi0/0'],'Input odnosi się do punktu obserwacji przepływów na interfejsie. Nie jest kierunkiem wysyłania rekordów eksportera.')
Q('Cache bez kolektora','Czy monitor bez przypisanego eksportera może gromadzić dane w lokalnym cache na wspieranej platformie?', ['Tak, eksport jest osobnym elementem','Nie, cache istnieje wyłącznie na kolektorze','Tak, ale tylko dane DNS','Nie, każdy rekord musi być zaszyfrowany'],'Lokalny cache i eksport są rozdzielone. Brak eksportera nie oznacza automatycznie braku lokalnych danych.')
C('Rekord i exporter','Istnieją rekord REC i exporter EXP. Powiąż je z monitorem MON.','flow monitor MON\n record {{b0}}\n exporter {{b1}}',[(['REC'],'identifier'),(['EXP'],'identifier')],'Monitor odwołuje się do istniejących nazw. Definicja monitora nie oznacza jeszcze przypięcia do interfejsu.')
Q('Dwa przepływy czy jeden','Klucz rekordu zawiera tylko IPv4 source i destination. Dwie rozmowy mają te same IP, lecz różne porty TCP. Przy tym kluczu:', ['Mogą trafić do tego samego wpisu przepływu','Zawsze muszą utworzyć dwa wpisy','Port kolektora automatycznie je rozdziela','Każdy pakiet tworzy trwały osobny rekord'],'Rozdział wynika z pól match. Aby odróżniać porty, należy uwzględnić je w kluczu odpowiedniego rekordu.')
C('Port i wersja eksportu','Kolektor nasłuchuje na UDP 2055 i oczekuje NetFlow v9. Uzupełnij exporter.','flow exporter EXP\n destination 192.0.2.50\n transport udp {{b0}}\n export-protocol {{b1}}',['2055','netflow-v9'],'Port musi odpowiadać konfiguracji kolektora. NetFlow v9 korzysta z szablonów opisujących rekordy.')
Q('Active timeout','Jaki jest cel active timeout dla długotrwałego przepływu w typowym cache normal?', ['Okresowe raportowanie danych mimo dalszego trwania ruchu','Zamknięcie sesji TCP użytkownika','Wyłączenie interfejsu po czasie','Wymuszenie odświeżenia DHCP'],'Active timeout ogranicza czas oczekiwania na dane o trwającym przepływie. Nie steruje sesją aplikacji użytkownika.')
Q('Brak szablonu','Kolektor odbiera datagramy NetFlow v9, ale nie potrafi zinterpretować rekordów nowego eksportera. Czego może brakować?', ['Szablonu opisującego pola rekordu','Trasy BGP do każdego hosta z rekordu','Identycznego numeru VLAN na kolektorze','Pełnego payloadu TCP w każdym rekordzie'],'NetFlow v9 jest oparty na szablonach. Odbiorca musi znać format, a nie tylko otrzymywać datagramy z danymi.')
Q('Cache rośnie, eksport nie dociera','Lokalny cache monitora zawiera ruch, lecz kolektor nie odbiera UDP. Co sprawdzić najpierw?', ['Exporter, routing do kolektora, źródło eksportu i ACL','Wyłącznie zmianę match ipv4 source na destination','Wyłącznie maskę hosta obserwowanego przepływu','Wyłącznie priorytet STP portu użytkownika'],'Obserwacja działa przynajmniej lokalnie. Teraz sprawdź odrębną ścieżkę eksportu i zgodność odbiorcy.')
C('Przypięcie monitora','REC i EXP istnieją. Utwórz MON, wskaż te obiekty i przypnij monitor do wejścia Gi0/0.','flow monitor MON\n record {{b0}}\n exporter {{b1}}\nexit\ninterface GigabitEthernet0/0\n ip flow monitor MON {{b2}}',[(['REC'],'identifier'),(['EXP'],'identifier'),'input'],'Monitor zaczyna obserwować wskazany kierunek po zastosowaniu na wspieranym interfejsie. Wsparcie zależy od platformy.')
Q('Sampling a dokładność','Monitor obserwuje próbkę ruchu z samplerem 1 na 100 pakietów. Czy surowy licznik próbek jest równy dokładnej liczbie wszystkich pakietów?', ['Nie; potrzebna jest interpretacja próbkowania, a estymacja nie jest dokładnym pomiarem','Tak, sampler kopiuje każdy pakiet sto razy','Tak, zawsze wystarczy odczytać licznik bez przeliczenia','Nie, sampling zawsze wyłącza cache'],'Próbkowanie zmniejsza obciążenie i dokładność szczegółów. Interpretuj rekordy wraz z informacją o samplerze.')
C('Rekord z licznikami','Zbuduj uproszczony rekord REC z kluczami source/destination IPv4 oraz niekluczowym licznikiem pakietów.','flow record REC\n match ipv4 {{b0}} address\n match ipv4 {{b1}} address\n collect counter {{b2}} long',['source','destination','packets'],'Ten uproszczony klucz grupuje według pary IP, bez rozróżniania portów. Collect packets long dodaje licznik pakietów.')
Q('Dwa punkty obserwacji','Ten sam ruch jest monitorowany na ingress i egress routera, a kolektor sumuje oba strumienie bez rozróżnienia punktu. Jakie ryzyko powstaje?', ['Podwójne liczenie tego samego ruchu','Automatyczne usunięcie duplikatów przez każdy kolektor','Podwojenie rzeczywistej przepustowości łącza','Utworzenie pętli routingu przez NetFlow'],'Rekordy trzeba analizować z kontekstem punktu i kierunku obserwacji. Dwa pomiary nie muszą oznaczać dwóch różnych transferów.')
end()
start('netconf','NETCONF — sesje, możliwości i operacje','4.6',[NET,'https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/configuration/26x/26x-programmability-cg/netconf_protocol.html',ACL])
Q('Transport NETCONF','Jaki jest typowy transport i domyślny port NETCONF na IOS XE?', ['SSH, TCP 830','HTTPS, TCP 443','SNMP, UDP 161','Telnet, TCP 23'],'NETCONF na IOS XE zwykle korzysta z podsystemu SSH na porcie 830. Nie jest to RESTCONF przez HTTPS.')
Q('Model i protokół','Jak rozdzielić role YANG i NETCONF?', ['YANG opisuje model danych, NETCONF przenosi operacje na danych','YANG szyfruje, NETCONF przydziela adresy','YANG jest portem TCP, NETCONF listą VLAN','Oba są wyłącznie językami CLI'],'Model definiuje strukturę i ograniczenia danych; protokół umożliwia odczyt i zmianę danych modelu.')
C('Włączenie usługi','Na wspieranym IOS XE włącz model-driven NETCONF. Uwierzytelnianie i dostęp sieciowy są już przygotowane.','Router(config)# {{b0}}',['netconf-yang'],'netconf-yang włącza usługę NETCONF opartą na modelach YANG; nie zastępuje poprawnej konfiguracji kont i dostępu.')
Q('Kodowanie RPC','W jakim formacie zapisuje się standardowe komunikaty RPC NETCONF?', ['XML','Wyłącznie JSON','CSV','Dowolny tekst poleceń show'],'NETCONF używa XML do komunikatów protokołu. YANG nie jest sam formatem kodowania przesyłanej instancji danych.')
Q('Powitanie serwera','Co klient powinien sprawdzić w komunikacie hello serwera NETCONF?', ['Advertised capabilities','Tylko nazwę DNS klienta','Wyłącznie licznik pakietów interfejsu','Listę czcionek terminala'],'Capabilities informują o obsługiwanych funkcjach. Nie zakładaj wsparcia candidate lub rollback bez sprawdzenia.')
C('Odczyt sesji','Wyświetl sesje model-driven NETCONF na IOS XE. Uzupełnij ostatni człon polecenia.','Router# show netconf-yang {{b0}}',['sessions'],'Polecenie pomaga potwierdzić działającą sesję. Samo włączenie konfiguracji nie dowodzi, że klient nawiązał połączenie.')
Q('Get a get-config','Które rozróżnienie jest poprawne dla podstawowych operacji NETCONF?', ['get odczytuje konfigurację i stan, get-config konfigurację wskazanego datastore','get zawsze zapisuje konfigurację, get-config kasuje','Obie zawsze zwracają tylko startup-config','get-config odczytuje wyłącznie liczniki interfejsów'],'Get-config wskazuje źródłowy datastore konfiguracji. Get może obejmować także dane operacyjne.')
Q('Datastore running','Do czego odnosi się running w podstawowym modelu datastore NETCONF?', ['Aktywnej konfiguracji urządzenia','Wyłącznie archiwum kopii zapasowych','Wyłącznie wyników ping','Tablicy historii logowania klienta'],'Running reprezentuje aktualnie działającą konfigurację. Nie jest synonimem danych operacyjnych wszystkich funkcji.')
C('ACL usługi NETCONF','IOS XE wspiera service-level ACL. Istniejąca standardowa ACL MGMT-NC dopuszcza uprawnione źródła. Przypnij ją do NETCONF SSH.','netconf-yang {{b0}} access-list {{b1}}',['ssh',(['MGMT-NC'],'identifier')],'ACL usługi ogranicza źródła połączeń NETCONF. Jej stosowanie nie oznacza automatycznego przypięcia do RESTCONF.')
Q('Candidate nie jest pewne','Klient chce wykonać edit-config na candidate, lecz serwer nie reklamuje :candidate. Co zrobić?', ['Dostosować operację do faktycznie obsługiwanych datastore','Wysłać commit wielokrotnie aż zadziała','Założyć, że każdy IOS XE ma candidate','Zmienić XML na CSV'],'Obsługa candidate jest capability, a nie uniwersalnym założeniem. Możliwości urządzenia określają dostępny workflow.')
Q('Lock','Jaki jest cel operacji lock na datastore?', ['Ograniczenie konfliktów równoczesnych zmian danego datastore','Szyfrowanie każdego pakietu Ethernet','Blokada wszystkich portów fizycznych','Trwałe wyłączenie dostępu administracyjnego'],'Lock koordynuje dostęp do konfiguracji. Nie zastępuje uwierzytelnienia ani planu zarządzania zmianą.')
C('Zaufane źródło','Dopuść do nowej ACL NC-SOURCES tylko host 192.0.2.10, następnie przypnij ACL do NETCONF SSH. Platforma wspiera tę funkcję.','ip access-list standard {{b0}}\n permit host {{b1}}\nexit\nnetconf-yang ssh access-list {{b2}}',[(['NC-SOURCES'],'identifier'),'192.0.2.10'],'Ta luka zawiera tylko dwie wartości; nazwa przypiętej ACL jest podana jawnie w ostatecznym szablonie.')
# Two blanks at difficulty 2; retain explicit binding for clarity.
